        "salawat_kurz_title": ["de": "O Allah, sende Segen auf Muhammad und auf die Familie Muhammads.", "en": "O Allah, send blessings upon Muhammad and upon the family of Muhammad.", "ar": "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ", "tr": "Allah'ım, Muhammed'e ve Muhammed'in ailesine salat eyle.", "id": "Ya Allah, limpahkanlah shalawat kepada Muhammad dan kepada keluarga Muhammad.", "ms": "Ya Allah, limpahkanlah selawat kepada Muhammad dan kepada keluarga Muhammad.", "fr": "Ô Allah, bénis Muhammad et la famille de Muhammad.", "es": "Oh Allah, bendice a Muhammad y a la familia de Muhammad.", "ur": "اے اللہ! محمد پر اور آلِ محمد پر رحمت نازل فرما۔", "ru": "О Аллах, благослови Мухаммада и семейство Мухаммада.", "bn": "হে আল্লাহ! মুহাম্মদের ওপর এবং মুহাম্মদের পরিবারের ওপর রহমত বর্ষণ করুন।"],
        "salawat_lang_title": ["de": "Salawat Ibrahimiyah (O Allah, sende Segen auf Muhammad und auf die Familie Muhammads...)", "en": "Salawat Ibrahimiyah (O Allah, send blessings upon Muhammad and the family of Muhammad...)", "ar": "الصلاة الإبراهيمية", "tr": "Salavat-ı İbrahimiye (Allah'ım, Muhammed'e ve Muhammed'in ailesine salat eyle...)", "id": "Shalawat Ibrahimiyah (Ya Allah, limpahkanlah shalawat kepada Muhammad dan keluarga Muhammad...)", "ms": "Selawat Ibrahimiyah (Ya Allah, limpahkanlah selawat kepada Muhammad dan keluarga Muhammad...)", "fr": "Salawat Ibrahimiyah (Ô Allah, bénis Muhammad et la famille de Muhammad...)", "es": "Salawat Ibrahimiyah (Oh Allah, bendice a Muhammad y a la familia de Muhammad...)", "ur": "درود ابراہیمی (اے اللہ! محمد اور آلِ محمد پر رحمت بھیج...)", "ru": "Салават Ибрахимийя (О Аллах, благослови Мухаммада и семейство Мухаммада...)", "bn": "দুরুদে ইব্রাহিমী (হে আল্লাহ! মুহাম্মদ এবং তাঁর পরিবারের ওপর রহমত বর্ষণ করুন...)"],
        "salawat_reminder_body": ["de": "Sendest du heute Salawat auf unseren Propheten Muhammad ﷺ?", "en": "Will you send Salawat upon our Prophet Muhammad ﷺ today?", "ar": "هل صليت اليوم على نبينا محمد ﷺ؟"],
        "salawat_reminder_friday_body": ["de": "Heute ist Freitag! Es ist eine besondere Sunnah, vermehrt Salawat auf den Propheten ﷺ zu sprechen.", "en": "Today is Friday! It is a special Sunnah to send abundant Salawat upon the Prophet ﷺ.", "ar": "اليوم يوم الجمعة! من السنة المأكورة الإكثار من الصلاة على النبي ﷺ."],
