        "tasbih_alhamdulillah": ["de": "Subhanallah, walhamdulillah, wa la ilaha illallah, wallahu akbar", "en": "Subhanallah, walhamdulillah, wa la ilaha illallah, wallahu akbar", "ar": "سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ", "tr": "Sübhanallah, velhamdülillah, ve la ilahe illallah, vallahu ekber", "id": "Subhanallah, walhamdulillah, wa la ilaha illallah, wallahu akbar", "ms": "Subhanallah, walhamdulillah, wa la ilaha illallah, wallahu akbar", "fr": "Subhanallah, walhamdulillah, wa la ilaha illallah, wallahu akbar", "es": "Subhanallah, walhamdulillah, wa la ilaha illallah, wallahu akbar", "ur": "سبحان اللہ، والحمد للہ، ولا الہ الا اللہ، واللہ اکبر", "ru": "Субханаллах, вальхамдулиллях, ва ля иляха илляллах, валлаху акбар", "bn": "সুবহানাল্লাহ, আলহামদুলিল্লাহ, লা ইলাহা ইল্লাল্লাহ, আল্লাহু আকবার"],
        "tasbih_alhamdulillah_trans": ["de": "Gepriesen sei Allah, alles Lob gebührt Allah, es gibt keinen Gott außer Allah und Allah ist der Größte", "en": "Glory be to Allah, all praise is due to Allah, there is no god but Allah, and Allah is the greatest", "ar": "سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ", "tr": "Allah her türlü eksiklikten uzaktır, hamd Allah'a aittir, Allah'tan başka ilah yoktur ve Allah en büyüktür", "id": "Maha Suci Allah, segala puji bagi Allah, tidak ada sesembahan selain Allah, dan Allah Maha Besar", "ms": "Maha Suci Allah, segala puji bagi Allah, tiada tuhan selain Allah dan Allah Maha Besar", "fr": "Gloire à Allah, louange à Allah, il n'y a de divinité qu'Allah et Allah est le plus grand", "es": "Glorificado sea Allah, alabado sea Allah, no hay más dios que Allah y Allah es el más grande", "ur": "اللہ پاک ہے، سب تعریفیں اللہ کے لیے ہیں، اللہ کے سوا کوئی معبود نہیں اور اللہ سب سے بڑا ہے", "ru": "Пречист Аллах, хвала Аллаху, нет бога, кроме Аллаха, и Аллах Превелик", "bn": "আল্লাহ পবিত্র, সমস্ত প্রশংসা আল্লাহর, আল্লাহ ছাড়া কোনো উপাস্য নেই এবং আল্লাহ সর্বশ্রেষ্ঠ"],
        "tasbih_count_mode": ["de": "Tasbih Zählmodus", "en": "Tasbih Counting Mode", "ar": "طريقة عد التسبيح", "tr": "Tesbih Sayma Modu", "id": "Mode Penghitungan Tasbih", "ms": "Mod Kiraan Tasbih", "fr": "Mode de comptage du Tasbih", "es": "Modo de conteo de Tasbih", "ur": "تسبیح گننے کا طریقہ", "ru": "Режим подсчёта Тасбиха", "bn": "তাসবীহ গণনা মোড"],
        "tasbih_istighfar": ["de": "Ich bitte Allah um Vergebung", "en": "I seek forgiveness from Allah", "ar": "أستغفر الله وأتوب إليه", "tr": "Allah'tan bağışlanma diliyorum", "id": "Aku memohon ampun kepada Allah", "ms": "Aku memohon ampun kepada Allah", "fr": "Je demande pardon à Allah", "es": "Pido perdón a Allah", "ur": "میں اللہ سے بخشش مانگتا ہوں", "ru": "Прошу прощения у Аллаха", "bn": "আমি আল্লাহর কাছে ক্ষমা চাই"],
        "tasbih_lahawla": ["de": "La hawla wa la quwwata illa billah", "en": "La hawla wa la quwwata illa billah", "ar": "لا حول ولا قوة إلا بالله", "tr": "La havle ve la kuvvete illa billah", "id": "La hawla wa la quwwata illa billah", "ms": "La hawla wa la quwwata illa billah", "fr": "La hawla wa la quwwata illa billah", "es": "La hawla wa la quwwata illa billah", "ur": "لا حول ولا قوة الا باللہ", "ru": "Ля хауля ва ля куввата илля биллях", "bn": "লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ"],
        "tasbih_lahawla_trans": ["de": "Es gibt keine Macht noch Kraft außer durch Allah", "en": "There is no power nor strength except with Allah", "ar": "لا حول ولا قوة إلا بالله", "tr": "Güç ve kuvvet ancak Allah'tandır", "id": "Tiada daya dan kekuatan kecuali dengan pertolongan Allah", "ms": "Tiada daya dan upaya melainkan dengan pertolongan Allah", "fr": "Il n'y a de force ni de puissance qu'en Allah", "es": "No hay poder ni fuerza excepto con Allah", "ur": "اللہ کے سوا کوئی طاقت اور کوئی قوت نہیں", "ru": "Нет мощи и силы ни у кого, кроме Аллаха", "bn": "আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই"],
        "tasbih_lailahaillallah": ["de": "La ilaha illallah", "en": "La ilaha illallah", "ar": "لَا إِلَٰهَ إِلَّا ٱللَّٰهُ", "tr": "La ilahe illallah", "id": "La ilaha illallah", "ms": "La ilaha illallah", "fr": "La ilaha illallah", "es": "La ilaha illallah", "ur": "لا الہ الا اللہ", "ru": "Ля иляха илляллах", "bn": "লা ইলাহা ইল্লাল্লাহ"],
        "tasbih_lailahaillallah_trans": ["de": "Es gibt keinen Gott außer Allah", "en": "There is no deity but Allah", "ar": "لا إله إلا الله", "tr": "Allah'tan başka ilah yoktur", "id": "Tiada Tuhan selain Allah", "ms": "Tiada tuhan melainkan Allah", "fr": "Il n'y a de divinité qu'Allah", "es": "No hay más dios que Allah", "ur": "اللہ کے سوا کوئی معبود نہیں", "ru": "Нет бога, кроме Аллаха", "bn": "আল্লাহ ছাড়া কোনো উপাস্য নেই"],
        "tasbih_salawat": ["de": "O Allah, segne Muhammad", "en": "O Allah, send blessings upon Muhammad", "ar": "اللهم صل وسلم على نبينا محمد", "tr": "Allah'ım, Muhammed'e salat ve selam eyle", "id": "Ya Allah, limpahkanlah shalawat dan salam kepada Nabi Muhammad", "ms": "Ya Allah, limpahkanlah selawat dan salam kepada Nabi Muhammad", "fr": "Ô Allah, bénis et accorde la paix à Muhammad", "es": "Oh Allah, bendice a Muhammad", "ur": "اے اللہ! محمد پر رحمت اور سلامتی بھیج", "ru": "О Аллах, благослови Мухаммада и приветствуй", "bn": "হে আল্লাহ! মুহাম্মদের ওপর শান্তি ও রহমত বর্ষণ করুন"],
        "tasbih_sec": ["de": "Tasbih", "en": "Tasbih", "ar": "التسبيح", "tr": "Tesbih", "id": "Tasbih", "ms": "Tasbih", "fr": "Tasbih", "es": "Tasbih", "ur": "تسبیح", "ru": "Тасбих", "bn": "তাসবীহ"],
        "tasbih_subhanallah": ["de": "Subhan Allahi wa bihamdihi, Subhan Allahil-Adhim", "en": "Subhan Allahi wa bihamdihi, Subhan Allahil-Adhim", "ar": "سبحان الله وبحمده سبحان الله العظيم", "tr": "Subhanallahi ve bihamdihi, Subhanallahil-Azim", "id": "Subhanallahi wa bihamdihi, Subhanallahil-Adzim", "ms": "Subhanallahi wa bihamdihi, Subhanallahil-Azim", "fr": "Subhan Allahi wa bihamdihi, Subhan Allahil-Adhim", "es": "Subhan Allahi wa bihamdihi, Subhan Allahil-Adhim", "ur": "سبحان اللہ وبحمدہ، سبحان اللہ العظیم", "ru": "Субхан Аллахи ва бихамдихи, Субхан Аллахиль-Азим", "bn": "সুবহানাল্লাহি ওয়া বিহামদিহী, সুবহানাল্লাহিল আজিম"],
        "tasbih_subhanallah_trans": ["de": "Gepriesen sei Allah und Lob gebührt Ihm, gepriesen sei Allah der Allmächtige", "en": "Glory be to Allah and praise Him, glory be to Allah the Almighty", "ar": "سبحان الله وبحمده سبحان الله العظيم", "tr": "Allah'ı hamd ile tesbih ederim, Yüce Allah'ı tenzih ederim", "id": "Maha Suci Allah dan segala puji bagi-Nya, Maha Suci Allah Yang Maha Agung", "ms": "Maha Suci Allah dan segala puji bagi-Nya, Maha Suci Allah Yang Maha Agung", "fr": "Gloire à Allah et louange à Lui, gloire à Allah l'Immense", "es": "Glorificado sea Allah y alabado sea, glorificado sea Allah el Grandioso", "ur": "اللہ پاک ہے اور اسی کے لیے تمام تعریفیں ہیں، اللہ پاک ہے جو بہت عظمت والا ہے", "ru": "Пречист Аллах и хвала Ему, пречист Аллах Великий", "bn": "আল্লাহ পবিত্র এবং তাঁরই সমস্ত প্রশংসা, মহান আল্লাহ অতি পবিত্র"],
